insert into public.lessons (id, code, title, emoji, color, coming_soon, sort) values ('ticaret-hukuku', '1010', 'Ticaret Hukuku', '⚖️', 'primary', false, 0) on conflict (id) do update set code = excluded.code, title = excluded.title, emoji = excluded.emoji, color = excluded.color, sort = excluded.sort;
insert into public.sections (id, lesson_id, title, emoji, sort) values ('ticaret-hukuku-01', 'ticaret-hukuku', 'Şirket türleri ve sermaye', '🏢', 1) on conflict (id) do update set title = excluded.title, emoji = excluded.emoji, sort = excluded.sort;
insert into public.cards (id, section_id, number, text, sort) values
  ('ticaret-hukuku-001', 'ticaret-hukuku-01', 1, 'Kollektif ve adi komandit **şahıs şirketi**; anonim, limited ve paylı komandit **sermaye şirketidir**.', 0),
  ('ticaret-hukuku-002', 'ticaret-hukuku-01', 2, 'Kooperatif ticaret şirketidir; TTK’daki **şahıs-sermaye ayrımının dışındadır**.', 1),
  ('ticaret-hukuku-003', 'ticaret-hukuku-01', 3, 'Adi şirket **TBK’ya tabidir**, ticaret şirketi değildir ve **tüzel kişiliği yoktur**.', 2),
  ('ticaret-hukuku-004', 'ticaret-hukuku-01', 4, 'Tüm ticaret şirketleri **tüzel kişidir**; TTK’da hüküm yoksa uygun ölçüde TMK ve TBK adi şirket hükümleri uygulanır.', 3),
  ('ticaret-hukuku-005', 'ticaret-hukuku-01', 5, 'TBK m.147’deki belirli ortaklık ilişkisi alacaklarında kural **5 yıl** zamanaşımıdır; TTK’nın özel süreleri saklıdır.', 4),
  ('ticaret-hukuku-006', 'ticaret-hukuku-01', 6, 'Limitedde asgari sermaye **50.000 TL**, esas sermayeli AŞ’de **250.000 TL**, kapalı kayıtlı AŞ’de **500.000 TL’dir**.', 5),
  ('ticaret-hukuku-007', 'ticaret-hukuku-01', 7, 'Açık kayıtlı AŞ’nin asgari sermayesi PDF’ye göre **2025’te 150 milyon TL**, **2026’da 200 milyon TL’dir**.', 6),
  ('ticaret-hukuku-008', 'ticaret-hukuku-01', 8, 'Asgari sermayeyi artırmaya **Cumhurbaşkanı** yetkilidir; limitedde **10 kat** sınırı vardır, AŞ’de bu üst sınır yoktur.', 7),
  ('ticaret-hukuku-009', 'ticaret-hukuku-01', 9, 'AŞ ve limitede **hizmet, kişisel emek, ticari itibar ve vadesi gelmemiş alacak** sermaye konulamaz.', 8),
  ('ticaret-hukuku-010', 'ticaret-hukuku-01', 10, 'Ayni sermaye **nakden değerlendirilebilir ve devredilebilir** olmalı; üzerinde **sınırlı ayni hak, haciz veya tedbir** bulunmamalıdır.', 9),
  ('ticaret-hukuku-011', 'ticaret-hukuku-01', 11, 'Taşınmaz sermaye **tapuya şerh**, taşınır **güvenilir kişiye tevdi**, fikrî hak **özel sicile kayıt** ile güvenceye alınır.', 10),
  ('ticaret-hukuku-012', 'ticaret-hukuku-01', 12, 'AŞ’de ayni sermayeye **merkezdeki asliye ticaret mahkemesinin atadığı bilirkişiler** değer biçer.', 11),
  ('ticaret-hukuku-013', 'ticaret-hukuku-01', 13, 'Sermaye konulan muaccel alacak **sözleşme tarihinden 1 ayda** tahsil edilmelidir; ortak tahsil edilmeden borcundan kurtulmaz.', 12),
  ('ticaret-hukuku-014', 'ticaret-hukuku-01', 14, 'AŞ’de nakit itibari bedelin **en az %25’i tescilden önce**, kalanı **tescili izleyen 24 ayda** ödenir; primin **tamamı tescilden önce** ödenir.', 13),
  ('ticaret-hukuku-015', 'ticaret-hukuku-01', 15, 'Kuruluş nakdi **5411 sayılı Kanuna tabi bankada şirket adına özel hesaba** yatırılır; şirket parayı sicil yazısıyla alır.', 14),
  ('ticaret-hukuku-016', 'ticaret-hukuku-01', 16, 'Noter onayından itibaren **3 ayda tüzel kişilik kazanılmazsa** bankadaki para sicil yazısıyla yatıranlara iade edilir.', 15),
  ('ticaret-hukuku-017', 'ticaret-hukuku-01', 17, 'SerPK kapsamındaki ihraçta kural **tam ve nakden ödeme**; istisna belirleme yetkisi **SPK’dadır**.', 16),
  ('ticaret-hukuku-018', 'ticaret-hukuku-01', 18, 'Sermaye ifa davasını AŞ, limited ve paylı komanditte **yalnız şirket**; şahıs şirketinde **ortak da** açabilir.', 17),
  ('ticaret-hukuku-019', 'ticaret-hukuku-01', 19, 'Sermaye gecikmesinde tazminat için **ihtar**; taahhüdü koruyan tedbir sonrası davada **tescil-ilandan başlayan 2 hafta** aranır.', 18),
  ('ticaret-hukuku-020', 'ticaret-hukuku-01', 20, 'AŞ’de **ıskata YK** karar verir; ihtarda **1 ay** ödeme süresi tanınır ve yalnız **ödenmeyen paylar** etkilenir.', 19),
  ('ticaret-hukuku-021', 'ticaret-hukuku-01', 21, 'Şahıs şirketi ortağının alacaklısı **kâr ve tasfiye payına**; sermaye şirketinde ayrıca **senetli/senetsiz payın haczine** başvurabilir.', 20),
  ('ticaret-hukuku-022', 'ticaret-hukuku-01', 22, 'Payın itibari değeri **en az 1 kuruştur**, 1 kuruşun katlarıyla artar; Cumhurbaşkanı bu değeri **100 katına** kadar artırabilir.', 21),
  ('ticaret-hukuku-023', 'ticaret-hukuku-01', 23, 'Pay senedi **nama veya hamiline** olur; **emre yazılı pay senedi olmaz**.', 22),
  ('ticaret-hukuku-024', 'ticaret-hukuku-01', 24, 'Şirketin hak ehliyeti işletme konusuyla sınırlı değildir; **ultra vires kaldırılmıştır**.', 23),
  ('ticaret-hukuku-025', 'ticaret-hukuku-01', 25, 'Borsaya kote paylı şirketlerde **elektronik GK katılım ve oy sistemi zorunludur**; diğerlerinde tercihe bağlıdır.', 24)
insert into public.sections (id, lesson_id, title, emoji, sort) values ('ticaret-hukuku-02', 'ticaret-hukuku', 'Birleşme, bölünme ve tür değiştirme', '🔀', 2) on conflict (id) do update set title = excluded.title, emoji = excluded.emoji, sort = excluded.sort;
insert into public.cards (id, section_id, number, text, sort) values
  ('ticaret-hukuku-026', 'ticaret-hukuku-02', 26, 'Birleşmede **devrolunan şirket tasfiyesiz sona erer**; aktif ve pasif **külli halefiyetle** geçer.', 0),
  ('ticaret-hukuku-027', 'ticaret-hukuku-02', 27, 'Şahıs şirketi sermaye şirketi veya kooperatifle birleşirse **devrolunan** olmak zorundadır.', 1),
  ('ticaret-hukuku-028', 'ticaret-hukuku-02', 28, 'Bölünme **yalnız sermaye şirketleri ve kooperatifler** arasında mümkündür; tam bölünmede şirket biter, kısmide sürer.', 2),
  ('ticaret-hukuku-029', 'ticaret-hukuku-02', 29, 'Tür değiştirmede yeni tür **eski şirketin devamıdır**; sermaye şirketinden şahıs şirketine dönüşüm PDF’nin izin listesinde yoktur.', 3),
  ('ticaret-hukuku-030', 'ticaret-hukuku-02', 30, 'Birleşmede **sözleşme**; mevcut şirkete bölünmede **sözleşme**, yeni şirkete bölünmede **plan**; tür değiştirmede **plan** hazırlanır.', 4),
  ('ticaret-hukuku-031', 'ticaret-hukuku-02', 31, 'Genel rejimde AŞ/paylı komanditin birleşme-bölünmesinde **sermaye çoğunluğu temsil + mevcut oyların 3/4’ü** gerekir.', 5),
  ('ticaret-hukuku-032', 'ticaret-hukuku-02', 32, 'Genel rejimde AŞ/paylı komanditin tür değiştirmesinde **sermayenin 2/3’ü temsil + mevcut oyların 2/3’ü** gerekir.', 6),
  ('ticaret-hukuku-033', 'ticaret-hukuku-02', 33, 'Limitedde bu yapısal kararlarda **sermayenin en az 3/4’ü + tüm ortakların 3/4’ü** gerekir.', 7),
  ('ticaret-hukuku-034', 'ticaret-hukuku-02', 34, 'Kooperatif birleşme-bölünmesinde **verilen oyların 2/3’ü**; ek yük/sınırsız sorumlulukta **kayıtlı ortakların 3/4’ü** gerekir.', 8),
  ('ticaret-hukuku-035', 'ticaret-hukuku-02', 35, 'Kooperatif tür değişiminde **ortakların 2/3’ü temsil + mevcut oy çoğunluğu**; ek kişisel yükte **kayıtlı ortakların 2/3’ü** gerekir.', 9),
  ('ticaret-hukuku-036', 'ticaret-hukuku-02', 36, 'Kollektif/komandit birleşmesinde kural **oybirliği**, sözleşmeyle **3/4 ortak**; tür değişiminde sözleşmeyle **2/3 ortak** mümkündür.', 10),
  ('ticaret-hukuku-037', 'ticaret-hukuku-02', 37, 'Sermaye şirketinin kooperatife dönüşmesi ve limitede geçiş/devralmada ek kişisel yük doğması gibi hâllerde **tüm ortakların onayı** aranır.', 11),
  ('ticaret-hukuku-038', 'ticaret-hukuku-02', 38, 'Paylı komandit devralmada **tüm komanditelerin yazılı onayı** da gerekir.', 12),
  ('ticaret-hukuku-039', 'ticaret-hukuku-02', 39, 'Oran korunmayan bölünmede **devreden şirketin oy hakkı olan ortaklarının %90’ı** gerekir.', 13),
  ('ticaret-hukuku-040', 'ticaret-hukuku-02', 40, 'Birleşmede ayrılma akçesi için PDF, şahısta **oy hakkı olan ortakların**, sermayede **mevcut oy haklarının %90’ını** verir.', 14),
  ('ticaret-hukuku-041', 'ticaret-hukuku-02', 41, 'Halka açık şirketlerde yapısal kararlara ilişkin **özel SerPK nisapları** genel TTK oranlarıyla birlikte gözetilir.', 15),
  ('ticaret-hukuku-042', 'ticaret-hukuku-02', 42, 'Bilanço ile ilgili işlem tarihi arasında **6 aydan fazla süre veya önemli malvarlığı değişimi** varsa ara bilanço gerekir.', 16),
  ('ticaret-hukuku-043', 'ticaret-hukuku-02', 43, 'İnceleme belgeleri GK’dan önce birleşmede **30 gün**, bölünmede **2 ay**, tür değiştirmede **30 gün** açık tutulur.', 17),
  ('ticaret-hukuku-044', 'ticaret-hukuku-02', 44, 'Birleşmede belge tevdi yeri **tevdiden en az 3 iş günü önce** ilan edilir; kural son **3 yılın** tablolarının sunulmasıdır.', 18),
  ('ticaret-hukuku-045', 'ticaret-hukuku-02', 45, 'KOBİ’lerde **tüm ortakların onayıyla** rapordan vazgeçilebilir; birleşme-bölünmede incelemeden vazgeçme de düzenlenir.', 19),
  ('ticaret-hukuku-046', 'ticaret-hukuku-02', 46, 'Denkleştirme ödemesi **gerçek pay değerinin en çok %10’udur**; denkleştirme davasında bu sınır uygulanmaz.', 20),
  ('ticaret-hukuku-047', 'ticaret-hukuku-02', 47, 'Kolaylaştırılmış birleşmede **%100 oy payı sahipliği** veya ek şartlarla **en az %90 sahiplik** kolaylık sağlar; %90 yolunda inceleme **tescil başvurusundan 30 gün önce** sunulur.', 21),
  ('ticaret-hukuku-048', 'ticaret-hukuku-02', 48, 'Birleşme-bölünmede alacaklı ilanı **7 gün arayla 3 kez**; birleşmede teminat istemi **geçerlilikten 3 ay**, bölünmede **ilanlardan 3 aydır**.', 22),
  ('ticaret-hukuku-049', 'ticaret-hukuku-02', 49, 'Yapısal denkleştirme davası **ilandan 2 ay**; iptal **ilandan 2 ay**, ilan gerekmiyorsa **tescilden 2 ay** içinde açılır.', 23),
  ('ticaret-hukuku-050', 'ticaret-hukuku-02', 50, 'Yapısal kusur sorumluluğunda süre **zarar ve sorumluyu öğrenmeden 2 yıl, fiilden 5 yıl**; şahıs ortağının eski borçlarında kural **birleşme ilanından 3 yıldır**.', 24),
  ('ticaret-hukuku-051', 'ticaret-hukuku-02', 51, 'İşçi geçişe itiraz ederse sözleşme **kanuni işten çıkarma süresi sonunda** biter; itiraz etmezse geçer.', 25)
insert into public.sections (id, lesson_id, title, emoji, sort) values ('ticaret-hukuku-03', 'ticaret-hukuku', 'Şirketler topluluğu ve kuruluş', '🧩', 3) on conflict (id) do update set title = excluded.title, emoji = excluded.emoji, sort = excluded.sort;
insert into public.cards (id, section_id, number, text, sort) values
  ('ticaret-hukuku-052', 'ticaret-hukuku-03', 52, 'TTK hâkimiyetinde oy çoğunluğu, yönetim çoğunluğunu seçtirme veya sözleşmesel/fiilî hâkimiyet esastır; **pay çoğunluğu karinedir**.', 0),
  ('ticaret-hukuku-053', 'ticaret-hukuku-03', 53, 'Hâkimiyet sözleşmesi **tescil ve ilanla** geçerli olur; hâkim teşebbüs tacir sayılır.', 1),
  ('ticaret-hukuku-054', 'ticaret-hukuku-03', 54, 'Halka açıkta yönetim kontrolü **oyların %50’sinden fazlası** veya YK çoğunluğunu seçme/aday gösterme imtiyazıdır; **zorunlu pay alım teklifi** doğurur.', 2),
  ('ticaret-hukuku-055', 'ticaret-hukuku-03', 55, 'Karşılıklı iştirak, şirketlerin birbirlerinin **en az %25 payına** sahip olmasıdır; bilerek giren ilgili hakların **yalnız 1/4’ünü** kullanır, özel hâkimiyet istisnaları saklıdır.', 3),
  ('ticaret-hukuku-056', 'ticaret-hukuku-03', 56, '**%5-10-20-25-33-50-67-100** sermaye basamaklarına ulaşma veya altına düşme, işlemden sonraki **10 günde** bildirilir; yapılmazsa oy dâhil haklar donar.', 4),
  ('ticaret-hukuku-057', 'ticaret-hukuku-03', 57, 'Bağlı şirket YK’sı, ilişkiler raporunu faaliyet yılının **ilk 3 ayında** hazırlar.', 5),
  ('ticaret-hukuku-058', 'ticaret-hukuku-03', 58, 'Azlığın payını satın alma hakkı için **en az %90 pay ve oy** ile azlığın engelleyici/dürüstlüğe aykırı davranışı gibi ek koşullar gerekir.', 6),
  ('ticaret-hukuku-059', 'ticaret-hukuku-03', 59, 'Tam hâkimiyet **%100 pay ve oy** sahipliğidir; ödeme gücünü aşan veya varlığı tehlikeye atan talimat verilemez.', 7),
  ('ticaret-hukuku-060', 'ticaret-hukuku-03', 60, 'Bağlı şirket kaybı **aynı faaliyet yılında** giderilmeli veya **yıl sonuna kadar** belirli denk istem tanınmalıdır.', 8),
  ('ticaret-hukuku-061', 'ticaret-hukuku-03', 61, 'Toplulukta belirli önemli kararlara itiraz eden ortağın dava süresi **GK kararından veya YK kararının ilanından 2 yıldır**.', 9),
  ('ticaret-hukuku-062', 'ticaret-hukuku-03', 62, 'Toplulukta m.207 kapsamında hile-dolan bildirilmişse **her pay sahibi doğrudan mahkemeden özel denetim isteyebilir**; azlık/GK aşaması gerekmez.', 10),
  ('ticaret-hukuku-063', 'ticaret-hukuku-03', 63, 'AŞ **tek gerçek veya tüzel kişiyle** kurulabilir; **tüzel kişiliği ticaret siciline tescille** kazanır.', 11),
  ('ticaret-hukuku-064', 'ticaret-hukuku-03', 64, 'AŞ borçlarından **bütün malvarlığıyla**; ortak taahhüt ettiği pay bedeliyle **yalnız şirkete karşı** sorumludur.', 12),
  ('ticaret-hukuku-065', 'ticaret-hukuku-03', 65, 'ES’yi imzalayıp pay taahhüt eden kurucudur; başkası hesabına hareket edilirse **hesabına işlem yapılan da kuruluş sorumluluğu bakımından kurucudur**.', 13),
  ('ticaret-hukuku-066', 'ticaret-hukuku-03', 66, 'ES **yazılı** yapılır; kaynakta bütün kurucuların imzalarının **noter onayı** öngörülür, onayla **ön şirket** doğar.', 14),
  ('ticaret-hukuku-067', 'ticaret-hukuku-03', 67, 'Ayni sermaye, ayın/işletme devralma veya kurucuya özel menfaat varsa **nitelikli ani kuruluş** söz konusudur.', 15),
  ('ticaret-hukuku-068', 'ticaret-hukuku-03', 68, 'Kuruluş belgeleri **ES, değerleme raporları ve kuruluşla ilgili sözleşmelerdir**; şirket nüshaları **5 yıl** saklar.', 16),
  ('ticaret-hukuku-069', 'ticaret-hukuku-03', 69, 'Kurucuya sermayeyi azaltan para/bedelsiz pay verilemez; yedek ve ortaklara **%5** ayrıldıktan sonra kalanın **en çok %10’u** kurucu intifasına ayrılabilir.', 17),
  ('ticaret-hukuku-070', 'ticaret-hukuku-03', 70, 'Dağıtılabilir kâr varsa kurucu intifa payı dağıtmama kararına rağmen ödenir; ilgili AŞ’ler **halka arzdan önce kurucu intifalarını bedelsiz iptal eder**.', 18),
  ('ticaret-hukuku-071', 'ticaret-hukuku-03', 71, 'Kuruluş sonrası ayın/işletme devralma-kiralaması **tescilden 2 yıl içinde** yapılmış ve bedel **sermayenin %10’unu aşmışsa** m.356 uygulanır.', 19),
  ('ticaret-hukuku-072', 'ticaret-hukuku-03', 72, 'm.356 işleminde mahkeme bilirkişisi, **%75 tüm sermaye olumlu oyu**, tescil-ilan ve kaynakta **en az 6 ay internet yayını** gerekir.', 20),
  ('ticaret-hukuku-073', 'ticaret-hukuku-03', 73, 'Kuruluş aykırılığında tescilli AŞ’nin yokluk/butlanı değil, **tescil ve ilandan 3 ay içinde feshi** istenir.', 21),
  ('ticaret-hukuku-074', 'ticaret-hukuku-03', 74, 'Kuruluş feshi davasını **YK, Ticaret Bakanlığı, ilgili alacaklı veya pay sahibi** merkezdeki asliye ticarette açar.', 22),
  ('ticaret-hukuku-075', 'ticaret-hukuku-03', 75, 'Tescilden önceki pay taahhüdü devri **şirkete karşı ileri sürülemez**; tedrici kuruluş kaldırılmıştır.', 23)
insert into public.sections (id, lesson_id, title, emoji, sort) values ('ticaret-hukuku-04', 'ticaret-hukuku', 'Kurumlar, izinler ve TSRS', '🏛️', 4) on conflict (id) do update set title = excluded.title, emoji = excluded.emoji, sort = excluded.sort;
insert into public.cards (id, section_id, number, text, sort) values
  ('ticaret-hukuku-076', 'ticaret-hukuku-04', 76, 'TTK **6102**, TBK **6098**, SerPK **6362**, Bankacılık Kanunu **5411** sayılıdır.', 0),
  ('ticaret-hukuku-077', 'ticaret-hukuku-04', 77, 'Sigortacılık **5684**, bireysel emeklilik **4632**, ödeme/e-para **6493**, yayın hizmetleri **6112** sayılı kanunlara bağlanır.', 1),
  ('ticaret-hukuku-078', 'ticaret-hukuku-04', 78, 'Lisanslı depoculuk **5300**, umumi mağazalar **2699**, SMMM/YMM mesleği **3568** sayılı kanuna tabidir.', 2),
  ('ticaret-hukuku-079', 'ticaret-hukuku-04', 79, 'Bakanlık izin listesindeki AŞ’lerin hem **kuruluşu hem ES değişikliği Ticaret Bakanlığı iznine** tabidir.', 3),
  ('ticaret-hukuku-080', 'ticaret-hukuku-04', 80, '**Bankalar; finansal kiralama, faktoring, tüketici finansmanı/kart hizmetleri, varlık yönetimi, sigorta ve döviz büfesi şirketleri** Bakanlık izin listesindedir.', 4),
  ('ticaret-hukuku-081', 'ticaret-hukuku-04', 81, '**AŞ holdingler, SerPK’ya tabi şirketler ve ürün ihtisas borsaları** Bakanlık izin listesindedir.', 5),
  ('ticaret-hukuku-082', 'ticaret-hukuku-04', 82, '**Umumi mağazalar, lisanslı depolar, bağımsız denetim ve gözetim şirketleri** Bakanlık izin listesindedir.', 6),
  ('ticaret-hukuku-083', 'ticaret-hukuku-04', 83, '**Teknoloji geliştirme bölgesi yönetici şirketleri ile serbest bölge kurucu/işleticileri** Bakanlık izin listesindedir.', 7),
  ('ticaret-hukuku-084', 'ticaret-hukuku-04', 84, 'Bakanlık izne tabi kuruluş/ES değişikliğini **emredici hükümlere uygunluk** yönünden inceler.', 8),
  ('ticaret-hukuku-085', 'ticaret-hukuku-04', 85, 'Halka açıkta ES değişikliği **SPK uygun görüşü**; kayıtlı sermayeye geçiş **SPK izni**; halka arz izahnamesi **SPK onayı** gerektirir.', 9),
  ('ticaret-hukuku-086', 'ticaret-hukuku-04', 86, 'Kapalı AŞ’nin kayıtlı sermayeye geçiş iznini **Ticaret Bakanlığı** verir; kapalı AŞ’nin halka arz edilmeyen **pay ihracı SerPK dışındadır**.', 10),
  ('ticaret-hukuku-087', 'ticaret-hukuku-04', 87, 'Bağımsız denetimde en üst otorite ve denetçi yetkilendiren kurum **KGK’dır**; kaynakta KAMUDESK adı da kullanılır.', 11),
  ('ticaret-hukuku-088', 'ticaret-hukuku-04', 88, 'Bağımsız denetime tabi şirket kapsamını **Cumhurbaşkanı**, TMS uygulama kapsamını **KGK** belirler.', 12),
  ('ticaret-hukuku-089', 'ticaret-hukuku-04', 89, 'Ödeme ve elektronik para kuruluşları denetim listesinde **TCMB/6493**; bankalar ve ilgili finansal şirketler **BDDK/5411** bağlantısıyla yer alır.', 13),
  ('ticaret-hukuku-090', 'ticaret-hukuku-04', 90, 'Kaydî haklar ve pay sahibi bilgileri **MKK** nezdinde izlenir; MKK, SPK’nın izin/onay görevini üstlenmez.', 14),
  ('ticaret-hukuku-091', 'ticaret-hukuku-04', 91, 'Kurumsal yönetimin dört ilkesi **adillik, şeffaflık, hesap verebilirlik ve sorumluluktur**.', 15),
  ('ticaret-hukuku-092', 'ticaret-hukuku-04', 92, 'ES, TTK’nın AŞ hükümlerinden **yalnız kanunun izin verdiği ölçüde** sapabilir; kanunda düzenlenmeyen alanda uygun tamamlayıcı hüküm konulabilir.', 16),
  ('ticaret-hukuku-093', 'ticaret-hukuku-04', 93, 'İnternet sitesi zorunluluğu **m.397/4 kapsamında bağımsız denetime tabi sermaye şirketleri** içindir.', 17),
  ('ticaret-hukuku-094', 'ticaret-hukuku-04', 94, 'ESG, **çevresel, sosyal ve kurumsal yönetimsel** etkenlerdir; **TSRS’yi KGK** belirleyip yayımlar.', 18),
  ('ticaret-hukuku-095', 'ticaret-hukuku-04', 95, '**TSRS 1 genel sürdürülebilirlik açıklamaları**, **TSRS 2 iklim açıklamaları** standardıdır.', 19),
  ('ticaret-hukuku-096', 'ticaret-hukuku-04', 96, 'TSRS’nin ilgili listedeki eşik üçlüsü **aktif 500 milyon TL, net satış 1 milyar TL, çalışan 250** olup **en az 2 eşik art arda 2 raporlama döneminde aşılır**.', 20),
  ('ticaret-hukuku-097', 'ticaret-hukuku-04', 97, '**TMSF bünyesi dışındaki bankalar TSRS’ye eşiksiz tabidir**; TMSF bankası bu zorunlu banka uygulamasından muaftır.', 21),
  ('ticaret-hukuku-098', 'ticaret-hukuku-04', 98, 'TSRS listesindeki borsa ortaklıklarında **Yakın İzleme Pazarı ve belirtilen Girişim Sermayesi Pazarı** ortaklıkları hariç tutulur.', 22),
  ('ticaret-hukuku-099', 'ticaret-hukuku-04', 99, 'SPK sürdürülebilirlik ilkelerinde **gönüllülük ve uyulmuyorsa gerekçe açıklama**; TSRS kapsamına girende **zorunlu raporlama** vardır.', 23)
insert into public.sections (id, lesson_id, title, emoji, sort) values ('ticaret-hukuku-05', 'ticaret-hukuku', 'Yönetim kurulu: üyelik, görev ve karar', '👔', 5) on conflict (id) do update set title = excluded.title, emoji = excluded.emoji, sort = excluded.sort;
insert into public.cards (id, section_id, number, text, sort) values
  ('ticaret-hukuku-100', 'ticaret-hukuku-05', 100, 'AŞ’nin zorunlu organları **GK ve YK’dır**; denetçi şirket organı değildir.', 0),
  ('ticaret-hukuku-101', 'ticaret-hukuku-05', 101, 'YK kural olarak **en az 1 üye**; bankalar ve ilgili borsa ortaklıklarında **en az 5 üyedir**.', 1),
  ('ticaret-hukuku-102', 'ticaret-hukuku-05', 102, 'YK görev süresi **en çok 3 yıl**; ES aksini demiyorsa yeniden seçim mümkündür ve pay sahibi olma şartı yoktur.', 2),
  ('ticaret-hukuku-103', 'ticaret-hukuku-05', 103, 'YK üyesi ve tüzel kişinin gerçek temsilcisi **tam ehliyetli** olmalıdır; iflas ve ehliyet kaybı üyeliği sona erdirir.', 3),
  ('ticaret-hukuku-104', 'ticaret-hukuku-05', 104, 'Tüzel kişi YK üyesi olabilir; **tescil/ilan edilen tek gerçek kişi temsilci** toplantıya katılıp oy verir.', 4),
  ('ticaret-hukuku-105', 'ticaret-hukuku-05', 105, 'YK üyelerini **GK seçer ve görevden alır**; ilk YK ES ile belirlenir.', 5),
  ('ticaret-hukuku-106', 'ticaret-hukuku-05', 106, 'Boş üyeliğe YK’nın seçtiği kişi **ilk GK onayına** sunulur ve **selefin kalan süresini** tamamlar.', 6),
  ('ticaret-hukuku-107', 'ticaret-hukuku-05', 107, 'Birden çok üyeli YK kendi içinden **1 başkan ve en az 1 başkan vekili** seçer; ES başkan seçimini GK’ya bırakabilir.', 7),
  ('ticaret-hukuku-108', 'ticaret-hukuku-05', 108, '**7511 sayılı Kanunla 29.05.2024’te** başkan/vekilin her yıl seçilmesi zorunluluğu kaldırılmıştır.', 8),
  ('ticaret-hukuku-109', 'ticaret-hukuku-05', 109, 'Üye çoğunluğunun yazılı isteminde başkan toplantıyı **en geç 30 gün içinde yapılacak şekilde** çağırır; çağırmaz/ulaşılamazsa istem sahipleri çağırabilir.', 9),
  ('ticaret-hukuku-110', 'ticaret-hukuku-05', 110, 'Halka açıkta grup temsil hakkı **YK üye sayısının yarısını aşamaz**; bağımsız üyelik kuralları saklıdır.', 10),
  ('ticaret-hukuku-111', 'ticaret-hukuku-05', 111, 'Gerçek kişi YK üyeliğinde tescil **açıklayıcıdır**; tüzel kişi temsilcisi tescilinin kurucu niteliği kaynakta **tartışmalıdır**.', 11),
  ('ticaret-hukuku-112', 'ticaret-hukuku-05', 112, 'YK’nın devredilemeyen işleri **üst yönetim, teşkilat, finans düzeni, atamalar, üst gözetim, defter-rapor-GK ve borca batıklık bildirimidir**.', 12),
  ('ticaret-hukuku-113', 'ticaret-hukuku-05', 113, 'Müdür ve imza yetkilisi atama/görevden alma devredilemez; **şube müdürleri bu özel listeden hariçtir**.', 13),
  ('ticaret-hukuku-114', 'ticaret-hukuku-05', 114, 'GK’ya saklı **YK seçimi/azli, mali hakları, ibra ve önemli varlığın toptan satışı** YK tarafından üstlenilemez.', 14),
  ('ticaret-hukuku-115', 'ticaret-hukuku-05', 115, 'YK toplantısı **üye tam sayısının çoğunluğuyla**, karar **hazır üyelerin çoğunluğuyla** alınır; ES ağırlaştırabilir.', 15),
  ('ticaret-hukuku-116', 'ticaret-hukuku-05', 116, 'YK’da **vekille katılım veya başkası yerine oy** mümkün değildir; karar yazılı ve imzalı olmalıdır.', 16),
  ('ticaret-hukuku-117', 'ticaret-hukuku-05', 117, 'Toplantısız yazılı kararda öneri **tüm üyelere** sunulur, **kimse toplantı istemez** ve **tam sayı çoğunluğu** yazılı onay verir.', 17),
  ('ticaret-hukuku-118', 'ticaret-hukuku-05', 118, 'Başkanın **üstün oyu yoktur**; ilk eşitlikte konu ertelenir, ikinci eşitlikte öneri reddedilir.', 18),
  ('ticaret-hukuku-119', 'ticaret-hukuku-05', 119, 'Üye; kendisi, eşi, alt/üstsoyu ve **3. derece dâhil kan/kayın hısımlarının** kişisel menfaatinde müzakereye ve oya katılamaz.', 19),
  ('ticaret-hukuku-120', 'ticaret-hukuku-05', 120, 'Çatışmalı üye **nisapta sayılmaz**; yasağın varlığını kararlaştıran oylamaya da katılamaz.', 20),
  ('ticaret-hukuku-121', 'ticaret-hukuku-05', 121, 'Sermaye ve kanuni yedekler toplamının **1/2’si kayıpsa** YK derhâl GK’yı çağırıp önlem sunar.', 21),
  ('ticaret-hukuku-122', 'ticaret-hukuku-05', 122, 'Aynı toplamın **2/3’ü kayıpsa**, GK **1/3’le yetinme veya tamamlama** kararı vermezse şirket kendiliğinden sona erer.', 22),
  ('ticaret-hukuku-123', 'ticaret-hukuku-05', 123, 'Borca batıklıkta YK **devamlılık ve muhtemel satış değerleriyle** ara bilanço hazırlar; yetersizlikte mahkemeye bildirip iflas ister.', 23),
  ('ticaret-hukuku-124', 'ticaret-hukuku-05', 124, 'Borca batıklıkta açığı karşılayan alacakların **diğer tüm alacaklardan sonraya yazılı sıra gerilemesi** mahkeme bilirkişisince doğrulanırsa iflas istisnası uygulanabilir.', 24),
  ('ticaret-hukuku-125', 'ticaret-hukuku-05', 125, 'Borsada işlem görende risk komitesi zorunludur; diğer şirkette **denetçinin yazılı bildirimiyle** kurulur ve ilk rapor **bildirimi izleyen 1 ay sonunda** verilir.', 25),
  ('ticaret-hukuku-126', 'ticaret-hukuku-05', 126, 'Risk komitesi düzenli raporunu **2 ayda bir YK’ya**, ayrıca **denetçiye** verir.', 26)
insert into public.sections (id, lesson_id, title, emoji, sort) values ('ticaret-hukuku-06', 'ticaret-hukuku', 'YK: yetki devri, bilgi ve yasaklar', '🚫', 6) on conflict (id) do update set title = excluded.title, emoji = excluded.emoji, sort = excluded.sort;
insert into public.cards (id, section_id, number, text, sort) values
  ('ticaret-hukuku-127', 'ticaret-hukuku-06', 127, 'Yönetim devri için **ES yetkisi ve iç yönerge** gerekir; yönetim YK üyesine veya üçüncü kişiye bırakılabilir.', 0),
  ('ticaret-hukuku-128', 'ticaret-hukuku-06', 128, 'Temsil devrinde **en az 1 YK üyesi temsil yetkisini korumalıdır**; m.370/2 aynı ES yetkisi/iç yönerge şartını aramaz.', 1),
  ('ticaret-hukuku-129', 'ticaret-hukuku-06', 129, 'ES aksini demiyor ve YK tek kişilik değilse şirket **çift imzayla** temsil edilir.', 2),
  ('ticaret-hukuku-130', 'ticaret-hukuku-06', 130, 'YK üyesi temsilci **murahhas üye**, dışarıdan temsilci **müdür/murahhas müdür** adını alır.', 3),
  ('ticaret-hukuku-131', 'ticaret-hukuku-06', 131, 'm.371/7’de sınırlı yetkili yardımcı, **temsile yetkisiz YK üyesi veya hizmet akdiyle bağlı kişi** olabilir; iç yönerge ve kişi **tescil/ilan edilir**.', 4),
  ('ticaret-hukuku-132', 'ticaret-hukuku-06', 132, 'm.371/7 yardımcılarını **YK atar**; iç yönerge tek başına atama yapmaz ve zararlarından YK’nın **müteselsil sorumluluğu** vardır.', 5),
  ('ticaret-hukuku-133', 'ticaret-hukuku-06', 133, 'Kanuna uygun yetki devrinde devreden, **seçimde makul özen göstermemişse** sorumlu olur; devredilemeyen üst gözetim görevi sürer.', 6),
  ('ticaret-hukuku-134', 'ticaret-hukuku-06', 134, 'Genel temsilde yalnız **tescil/ilan edilmiş şube-merkez ve birlikte temsil** sınırları iyiniyetli üçüncü kişiye ileri sürülebilir.', 7),
  ('ticaret-hukuku-135', 'ticaret-hukuku-06', 135, 'Genel temsilcinin iç **konu veya tutar sınırı**, iyiniyetli üçüncü kişiye kural olarak ileri sürülemez; m.371/7 özel yolu ayrıdır.', 8),
  ('ticaret-hukuku-136', 'ticaret-hukuku-06', 136, 'Konu dışı temsil işlemi kural olarak şirketi bağlar; karşı tarafın bildiği/bilebileceği ispatlanmalıdır ve **ES ilanı tek başına yeterli değildir**.', 9),
  ('ticaret-hukuku-137', 'ticaret-hukuku-06', 137, 'Şirkete ihbar/bildirimde **birlikte temsil aranmaz**; yetkili temsilcilerden birine yapılması yeterlidir.', 10),
  ('ticaret-hukuku-138', 'ticaret-hukuku-06', 138, 'YK üyesinin toplantı içindeki bilgi talebi **reddedilemez**; toplantı dışında başkan, başkanın kendisi için **kurul izni** gerekir.', 11),
  ('ticaret-hukuku-139', 'ticaret-hukuku-06', 139, 'Bilgi talebi reddedilen YK üyesi konuyu **2 gün içinde YK’ya** getirir; ret/toplanmama hâlinde merkezdeki asliye ticarete gider, karar kesindir.', 12),
  ('ticaret-hukuku-140', 'ticaret-hukuku-06', 140, 'YK’nın ücret, huzur hakkı, ikramiye ve primini **GK** belirler; YK kendisi belirleyemez ve kâr payı için **ES hükmü de** gerekir.', 13),
  ('ticaret-hukuku-141', 'ticaret-hukuku-06', 141, 'Şirket iflasında YK üyelerinin **son 3 yıldaki** uygun ölçüyü aşan kazanç/ücretlerinden belirtilen kısmın iadesi istenebilir.', 14),
  ('ticaret-hukuku-142', 'ticaret-hukuku-06', 142, 'Şirketle işlem yasağında YK üyesi **GK izni** olmadan kendisi/başkası adına işlem yapamaz; butlanı **şirket** ileri sürebilir.', 15),
  ('ticaret-hukuku-143', 'ticaret-hukuku-06', 143, 'Pay sahibi şirkete ancak **vadesi gelmiş sermaye borcunu ödemişse ve serbest yedek+kâr geçmiş zararları karşılıyorsa** borçlanabilir.', 16),
  ('ticaret-hukuku-144', 'ticaret-hukuku-06', 144, 'Pay sahibi olmayan YK üyesi ve pay sahibi olmayan **eşi, alt/üstsoyu, 3. derece dâhil kan/kayın hısımları** şirkete nakit borçlanamaz; şirket kefalet/garanti/teminat veremez.', 17),
  ('ticaret-hukuku-145', 'ticaret-hukuku-06', 145, 'Bu borçlanma yasağında alacaklı **borçlanılan/yüklenilen tutar kadar doğrudan takip** yapabilir; PDF’de adli para cezası alt sınırı **300 gündür**.', 18),
  ('ticaret-hukuku-146', 'ticaret-hukuku-06', 146, 'Rekabet yasağı için **GK izni** gerekir; aynı iş türünde kendi/başkası hesabına işlem ve rakip şirkete **sınırsız sorumlu ortaklık** yasaktır.', 19),
  ('ticaret-hukuku-147', 'ticaret-hukuku-06', 147, 'Rekabet ihlalinde tazminat veya işlemi/menfaati şirkete mal etme seçimini **ihlalde bulunan dışındaki YK üyeleri** yapar.', 20),
  ('ticaret-hukuku-148', 'ticaret-hukuku-06', 148, 'Rekabet davasında süre **diğer üyelerin öğrenmesinden 3 ay, her hâlde fiilden 1 yıldır**.', 21),
  ('ticaret-hukuku-149', 'ticaret-hukuku-06', 149, 'Özen ölçüsü **tedbirli yönetici özeni**; işadamı kararında **ticari takdir, şirket menfaati, yeterli bilgi ve makullük** birlikte aranır.', 22),
  ('ticaret-hukuku-150', 'ticaret-hukuku-06', 150, 'Hile, kaynakları kötüye kullanma, emredici hükme aykırılık ve ihmal **işadamı kararı koruması dışındadır**; sır saklama görevden sonra da sürebilir.', 23)
insert into public.sections (id, lesson_id, title, emoji, sort) values ('ticaret-hukuku-07', 'ticaret-hukuku', 'Karar sakatlığı, sorumluluk ve ibra', '🩹', 7) on conflict (id) do update set title = excluded.title, emoji = excluded.emoji, sort = excluded.sort;
insert into public.cards (id, section_id, number, text, sort) values
  ('ticaret-hukuku-151', 'ticaret-hukuku-07', 151, 'YK kararlarında genel iptal yolu yoktur; **yokluk ve butlanı ilgili herkes süresiz** ileri sürebilir ve mahkeme resen dikkate alır.', 0),
  ('ticaret-hukuku-152', 'ticaret-hukuku-07', 152, 'm.391’de YK butlanı **eşit işlem, temel yapı/sermaye koruma, vazgeçilmez haklar ve diğer organa saklı yetki** gruplarıyla sayılır.', 1),
  ('ticaret-hukuku-153', 'ticaret-hukuku-07', 153, '**Dürüstlük kuralına aykırılık**, m.391’in açık butlan sayımında yer almaz; özel iptal hükümleri ayrıdır.', 2),
  ('ticaret-hukuku-154', 'ticaret-hukuku-07', 154, 'Kayıtlı sermayede YK kararı iptali **TTK’da ilandan 1 ay**, **SerPK’da ilandan 30 gün**; belirtilen avans kararında **ilandan 30 gündür**.', 3),
  ('ticaret-hukuku-155', 'ticaret-hukuku-07', 155, 'Kurucu, YK üyesi, yönetici ve tasfiye memuru **kusurlu yükümlülük ihlalinde** sorumludur; genel rejimde kusuru **davacı ispatlar**.', 4),
  ('ticaret-hukuku-156', 'ticaret-hukuku-07', 156, 'Şirket zararında pay sahibi dava açabilir fakat tazminatı **şirkete** ister; doğrudan kişisel zararda ödeme **zarar görene** yapılır.', 5),
  ('ticaret-hukuku-157', 'ticaret-hukuku-07', 157, 'Alacaklının dolaylı zarar davasında genel kural **şirketin iflası**; m.193 ve topluluk özel yollarında iflas şartı aranmaz.', 6),
  ('ticaret-hukuku-158', 'ticaret-hukuku-07', 158, 'Farklılaştırılmış teselsülde her sorumlu **kendi kusuru ve durumuna göre yüklenebilen zarar ölçüsünde** müteselsilen sorumludur.', 7),
  ('ticaret-hukuku-159', 'ticaret-hukuku-07', 159, 'Genel sorumluluk zamanaşımı **zarar+sorumluyu öğrenmeden 2 yıl, fiilden 5 yıl**; daha uzun ceza süresi saklıdır.', 8),
  ('ticaret-hukuku-160', 'ticaret-hukuku-07', 160, 'Sorumluluk davasında görevli mahkeme **asliye ticaret**; şirket merkezi, genel yetkiye ek yetki seçeneğidir.', 9),
  ('ticaret-hukuku-161', 'ticaret-hukuku-07', 161, 'İbrayı **GK** verir; oy imtiyazı kullanılamaz ve YK/imza yetkilisi **kendi payıyla** YK ibrasına oy veremez.', 10),
  ('ticaret-hukuku-162', 'ticaret-hukuku-07', 162, 'GK aksini demiyorsa bilanço onayı ibra sonucu doğurabilir; **bilinçli eksik/gizlenmiş bilanço ibra doğurmaz**.', 11),
  ('ticaret-hukuku-163', 'ticaret-hukuku-07', 163, 'Geçerli ibra **yeni GK kararıyla geri alınamaz**; kanuni şartlarla yargı yolu mümkündür.', 12),
  ('ticaret-hukuku-164', 'ticaret-hukuku-07', 164, 'Açıklanan ve ibra kapsamındaki olaylarda şirketin, olumlu oy verenin ve ibrayı bilerek pay alanın dava hakkı kalkar; diğer ortaklarda **ibradan 6 ay** sonra düşer.', 13),
  ('ticaret-hukuku-165', 'ticaret-hukuku-07', 165, 'İbra **şirket alacaklılarının dava hakkını etkilemez**.', 14),
  ('ticaret-hukuku-166', 'ticaret-hukuku-07', 166, 'Kuruluş/artırım sorumluluğu **şirketin tescilinden 4 yıl geçmeden** sulh/ibrayla kaldırılamaz; sonrasında GK onayı gerekir.', 15),
  ('ticaret-hukuku-167', 'ticaret-hukuku-07', 167, 'Kuruluş/artırım sulh-ibrasına kapalıda **%10**, açıkta **%5** azlık karşı çıkarsa GK onaylayamaz.', 16),
  ('ticaret-hukuku-168', 'ticaret-hukuku-07', 168, 'PDF’nin m.549 anlatımında belge/beyan düzenleyenin sorumluluğu **kusursuz**, katılanın sorumluluğu **kusura dayalıdır**.', 17),
  ('ticaret-hukuku-169', 'ticaret-hukuku-07', 169, 'Belgede sahtecilik/kasıtlı gerçeğe aykırı defter kaydının PDF’deki cezası **1-3 yıl hapis**tir.', 18),
  ('ticaret-hukuku-170', 'ticaret-hukuku-07', 170, 'Sermaye hakkında yanlış beyanın cezası **3 ay-2 yıl hapis veya adli para**; değerleme yolsuzluğunda **en az 90 gün adli paradır**.', 19),
  ('ticaret-hukuku-171', 'ticaret-hukuku-07', 171, 'Yasak halka para toplama cezası **6 ay-2 yıl hapis**; zorunlu siteyi kurmama **100-300 gün**, içeriği koymama **100 güne kadar adli paradır**.', 20),
  ('ticaret-hukuku-172', 'ticaret-hukuku-07', 172, 'Kamuyu aydınlatma belgesini imzalayan/başkası adına imzalanan tüzel kişiler zarardan **müteselsilen** sorumlu olabilir; yanlışlığı bilmediğini ve kast/ağır ihmali olmadığını ispat kurtuluş sağlar.', 21),
  ('ticaret-hukuku-173', 'ticaret-hukuku-07', 173, 'Kamuyu aydınlatma belgesi sorumluluğunda süre **zararın meydana gelmesinden 6 aydır**.', 22),
  ('ticaret-hukuku-174', 'ticaret-hukuku-07', 174, 'İzahnamede ilk sorumlu **ihraççı**; tahsil edilemiyorsa belirtilen diğer kişiler kusur/yüklenebilir zarar ölçüsünde sorumlu olabilir.', 23),
  ('ticaret-hukuku-175', 'ticaret-hukuku-07', 175, '**6183 mükerrer m.35**, şirketten tahsil edilemeyen/edilemeyeceği anlaşılan amme alacağını kanuni temsilciden tahsile imkân verir; tasfiye eski sorumluluğu kaldırmaz.', 24)
insert into public.sections (id, lesson_id, title, emoji, sort) values ('ticaret-hukuku-08', 'ticaret-hukuku', 'Genel kurul: çağrı, gündem ve özel kurul', '📣', 8) on conflict (id) do update set title = excluded.title, emoji = excluded.emoji, sort = excluded.sort;
insert into public.cards (id, section_id, number, text, sort) values
  ('ticaret-hukuku-176', 'ticaret-hukuku-08', 176, 'GK; **ES değişikliği, YK seçimi/azli/mali hakları/ibrası, denetçi seçimi, finansal-kâr kararları, fesih ve önemli varlığın toptan satışı** yetkilerini devredemez; kanuni istisnalar saklıdır.', 0),
  ('ticaret-hukuku-177', 'ticaret-hukuku-08', 177, 'Olağan GK **faaliyet dönemi sonundan 3 ay içinde** yapılır; olağanüstü GK gerektiğinde toplanır.', 1),
  ('ticaret-hukuku-178', 'ticaret-hukuku-08', 178, 'Çağrısız GK’da **tüm paylar hazır/temsil edilmiş olmalı ve kimse itiraz etmemelidir**; %100 katılım toplantı boyunca sürer, karar nisabı ayrıca uygulanır.', 2),
  ('ticaret-hukuku-179', 'ticaret-hukuku-08', 179, 'GK’yı kural olarak **YK, süresi dolsa bile** çağırır; tasfiye memuru görevleriyle ilgili çağrı yapabilir.', 3),
  ('ticaret-hukuku-180', 'ticaret-hukuku-08', 180, 'YK sürekli çalışamıyor veya yoksa **tek pay sahibi mahkeme izniyle** GK’yı çağırabilir; tahvil sahiplerinin çağrı yetkisi yoktur.', 4),
  ('ticaret-hukuku-181', 'ticaret-hukuku-08', 181, 'Azlık, kapalı AŞ’de **%10**, açık AŞ’de **%5 sermayedir**; çağrı/gündem istemi **noterle** YK’ya gönderilir.', 5),
  ('ticaret-hukuku-182', 'ticaret-hukuku-08', 182, 'Gündeme ekleme istemi **ilan ücretinin yatırılmasından önce** YK’ya ulaşmalıdır.', 6),
  ('ticaret-hukuku-183', 'ticaret-hukuku-08', 183, 'YK azlık talebini kabul ederse GK **en geç 45 günde yapılacak şekilde** çağrılır; yapmazsa istem sahipleri çağırır.', 7),
  ('ticaret-hukuku-184', 'ticaret-hukuku-08', 184, 'Ret veya **7 iş gününde olumlu cevap yokluğu** hâlinde azlık merkezdeki asliye ticarete gider; mahkeme kayyım atayabilir ve kararı kesindir.', 8),
  ('ticaret-hukuku-185', 'ticaret-hukuku-08', 185, 'Çağrı kapalı/genel rejimde **en az 2 hafta**, halka açıkta **en az 3 hafta** önce yapılır; **ilan ve toplantı günleri sayılmaz**.', 9),
  ('ticaret-hukuku-186', 'ticaret-hukuku-08', 186, 'Genel rejimde çağrı **TTSG ve ES’deki şekille**, site yükümlüsünde siteyle; açıkta **site, KAP ve SPK’nın belirlediği yerlerle** yapılır.', 10),
  ('ticaret-hukuku-187', 'ticaret-hukuku-08', 187, 'ES değişikliği gündemindeyse **eski-yeni metin**; ertelenmiş toplantıysa **sebep ve yeni nisap** çağrıda açıklanır.', 11),
  ('ticaret-hukuku-188', 'ticaret-hukuku-08', 188, 'Gündemde olmayan konu kural olarak karara bağlanamaz; bütün paylar hazırsa **oybirliğiyle madde eklenebilir**.', 12),
  ('ticaret-hukuku-189', 'ticaret-hukuku-08', 189, '**Özel denetim istemi, yıl sonu tablolarıyla ilgili YK değişimi, haklı sebeple YK azli ve eşit bilgi istemi** gündeme bağlılık istisnalarındandır.', 13),
  ('ticaret-hukuku-190', 'ticaret-hukuku-08', 190, 'Gündem sırası **hazır oyların çoğunluğuyla**; karara bağlanan konunun yeniden görüşülmesi **hazır bulunanların oybirliğiyle** değişir.', 14),
  ('ticaret-hukuku-191', 'ticaret-hukuku-08', 191, 'Kurumsal/organ/bağımsız temsilci hükümleri **7099 sayılı Kanunla kaldırılmıştır**; kaynakta eski m.428 süreci ayrıca anlatılır.', 15),
  ('ticaret-hukuku-192', 'ticaret-hukuku-08', 192, 'İmtiyazı ihlal eden ES değişikliği, YK’ya artırım yetkisi veya YK artırımı **özel kurul onayı olmadan uygulanamaz**.', 16),
  ('ticaret-hukuku-193', 'ticaret-hukuku-08', 193, 'Özel kurul toplantısı **imtiyazlı pay sermayesinin %60’ı**, karar **temsil edilen payların salt çoğunluğudur**.', 17),
  ('ticaret-hukuku-194', 'ticaret-hukuku-08', 194, 'YK özel kurulu **GK kararının ilanından 1 ayda** çağırır; çağırmazsa her imtiyazlı ortak **çağrı süresinin son gününden 15 günde** mahkemeye gider.', 18),
  ('ticaret-hukuku-195', 'ticaret-hukuku-08', 195, 'Onaylamama tutanağı **10 günde YK’ya** verilir; YK bu karara **karar tarihinden 1 ayda** dava açabilir.', 19),
  ('ticaret-hukuku-196', 'ticaret-hukuku-08', 196, 'İmtiyazlılar GK’da özel kurul nisaplarıyla olumlu oy vermişse **ayrı özel kurul gerekmez**.', 20),
  ('ticaret-hukuku-197', 'ticaret-hukuku-08', 197, 'Bakanlık iznine tabi şirkette **bütün GK’larda**; diğerlerinde **sermaye artırma/azaltma, kayıtlı sisteme giriş/çıkış/tavan artırma, faaliyet konusu ve birleşme/bölünme/tür değişimi** gündeminde Bakanlık temsilcisi gerekir.', 21),
  ('ticaret-hukuku-198', 'ticaret-hukuku-08', 198, '**Elektronik katılım sistemi uygulayan şirketlerin GK’larında ve yurt dışı GK’larda** Bakanlık temsilcisi gerekir.', 22),
  ('ticaret-hukuku-199', 'ticaret-hukuku-08', 199, 'Yurt dışındaki **imtiyazlı özel kurulda** temsilci zorunludur; temsilci giderini **şirket** karşılar.', 23),
  ('ticaret-hukuku-200', 'ticaret-hukuku-08', 200, 'Varsa murahhas üyeler ve **en az 1 YK üyesi** ile denetçi GK’da hazır bulunur; pay sahibi olmadan da görüş açıklayabilirler.', 24)
insert into public.sections (id, lesson_id, title, emoji, sort) values ('ticaret-hukuku-09', 'ticaret-hukuku', 'GK: katılım, oy, nisap ve dava', '🗳️', 9) on conflict (id) do update set title = excluded.title, emoji = excluded.emoji, sort = excluded.sort;
insert into public.cards (id, section_id, number, text, sort) values
  ('ticaret-hukuku-201', 'ticaret-hukuku-09', 201, 'GK’ya katılma ve oy hakkı **pay/belgeyi depo etme şartına bağlanamaz**; temsilci pay sahibi olmak zorunda değildir.', 0),
  ('ticaret-hukuku-202', 'ticaret-hukuku-09', 202, 'Aksi kararlaştırılmadıkça intifa sahibi katılıp oy verir; ortak mülkiyette **ortak temsilci** gerekir.', 1),
  ('ticaret-hukuku-203', 'ticaret-hukuku-09', 203, 'Katılım listesini **YK hazırlar, YK başkanı imzalar**; kayden izlenen paylarda liste kaynağı **MKK’dır**.', 2),
  ('ticaret-hukuku-204', 'ticaret-hukuku-09', 204, 'GK ES aksini demiyorsa **şirket merkezinde** yapılır; tek ortak GK kararını da **yazılı** alır.', 3),
  ('ticaret-hukuku-205', 'ticaret-hukuku-09', 205, 'Oy itibari pay değeriyle orantılıdır; her ortağın **en az 1 oyu** vardır ve kural olarak oy için **pay bedelinin 1/4’ü** ödenir.', 4),
  ('ticaret-hukuku-206', 'ticaret-hukuku-09', 206, 'Pay sahibi kendisi/eşi/alt-üstsoyu ve kanunda sayılan bağlantılı şirketlerle kişisel işlem/davada **oy kullanamaz**.', 5),
  ('ticaret-hukuku-207', 'ticaret-hukuku-09', 207, 'Şirketin kendi payları ve yavrunun ana şirket payları **toplantı nisabında sayılmaz**; ilgili oy hakları kullanılamaz/donar.', 6),
  ('ticaret-hukuku-208', 'ticaret-hukuku-09', 208, 'Oy imtiyazı **eşit itibari değere farklı oy** verilmesidir; kural üst sınır **pay başına 15 oy**, haklı sebep/kurumlaşma istisnasına mahkeme karar verir.', 7),
  ('ticaret-hukuku-209', 'ticaret-hukuku-09', 209, 'Oy imtiyazı **ES değişikliği, ibra ve sorumluluk davası açma** kararlarında kullanılamaz.', 8),
  ('ticaret-hukuku-210', 'ticaret-hukuku-09', 210, 'Temsilcinin talimata aykırı oyu **geçersiz olmaz**; tevdi temsilcisi zamanında özel talimat alamazsa genel talimat, o da yoksa **YK önerisi** yönünde oy verir.', 9),
  ('ticaret-hukuku-211', 'ticaret-hukuku-09', 211, 'Birikimli oy **oy sayısı × seçilecek YK sayısıdır**; ES’de açık hüküm, **sabit en az 3 üye**, grup/aday önerme hakkı ve oy imtiyazının yokluğu aranır.', 10),
  ('ticaret-hukuku-212', 'ticaret-hukuku-09', 212, 'Adi GK ilk toplantıda **sermayenin en az 1/4’üyle** toplanır; ikincide toplantı nisabı yoktur, karar **hazır oy çoğunluğudur**.', 11),
  ('ticaret-hukuku-213', 'ticaret-hukuku-09', 213, 'Genel ES değişikliğinde ilk toplantı **en az 1/2 sermaye**, en geç 1 ayda ikinci toplantı **en az 1/3 sermaye**; karar **mevcut oy çoğunluğudur**.', 12),
  ('ticaret-hukuku-214', 'ticaret-hukuku-09', 214, '**Zarar kapatmak için yük/ikincil yük koyma ve merkezin yurt dışına taşınması** tüm sermayenin oybirliğini gerektirir.', 13),
  ('ticaret-hukuku-215', 'ticaret-hukuku-09', 215, '**Konuyu tamamen değiştirme, imtiyazlı pay oluşturma ve nama pay devrini sınırlama** tüm sermayenin **en az %75 olumlu oyunu** gerektirir.', 14),
  ('ticaret-hukuku-216', 'ticaret-hukuku-09', 216, 'Oybirliği/%75 kararlarında sonraki toplantıda da **aynı ağır nisap** aranır.', 15),
  ('ticaret-hukuku-217', 'ticaret-hukuku-09', 217, 'Halka açıkta genel olarak SerPK/ES’de açık ağır oran yoksa **adi nisap** uygulanır; yurt dışı ve yük koyma istisnaları saklıdır.', 16),
  ('ticaret-hukuku-218', 'ticaret-hukuku-09', 218, 'Açıkta rüçhan kısıtlama/yetkisi, sermaye azaltımı ve önemli işlemlerde kural **toplantı nisabı olmadan katılan oy haklı payların 2/3’üdür**.', 17),
  ('ticaret-hukuku-219', 'ticaret-hukuku-09', 219, 'Bu özel açık işlemlerde **en az yarı sermaye hazırsa** karar katılan oy haklı payların **çoğunluğuyla** alınır; açık ağır ES oranı saklıdır.', 18),
  ('ticaret-hukuku-220', 'ticaret-hukuku-09', 220, 'GK yokluk/butlanı kural olarak **süresiz**; genel GK iptali **karardan 3 ayda** merkezdeki asliye ticarette ileri sürülür.', 19),
  ('ticaret-hukuku-221', 'ticaret-hukuku-09', 221, 'İptalde olağan ortak yolu **olumsuz oy ve tutanağa muhalefet**; belirtilen usul ihlalinde **karara etki** aranır.', 20),
  ('ticaret-hukuku-222', 'ticaret-hukuku-09', 222, 'YK organ olarak; tek YK üyesi **uygulama kişisel sorumluluğunu doğuracaksa** iptal davası açabilir; denetçinin bu yetkisi yoktur.', 21),
  ('ticaret-hukuku-223', 'ticaret-hukuku-09', 223, 'İptal davası icrayı kendiliğinden durdurmaz; **mahkeme durdurabilir** ve 3 aylık dava süresi dolmadan duruşma başlamaz.', 22),
  ('ticaret-hukuku-224', 'ticaret-hukuku-09', 224, 'Kesinleşen iptal/butlan hükmü **bütün ortaklara** etkilidir; kötü niyetli davacılar şirket zararından **müteselsilen** sorumludur.', 23),
  ('ticaret-hukuku-225', 'ticaret-hukuku-09', 225, 'SPK’nın m.92 özel yolunda iptal **tespitten 3 ay/işlemden 3 yıl**, yokluk-butlan tespiti **5 yıl** içinde istenir.', 24)
insert into public.sections (id, lesson_id, title, emoji, sort) values ('ticaret-hukuku-10', 'ticaret-hukuku', 'Denetim eşikleri ve denetçi', '🔍', 10) on conflict (id) do update set title = excluded.title, emoji = excluded.emoji, sort = excluded.sort;
insert into public.cards (id, section_id, number, text, sort) values
  ('ticaret-hukuku-226', 'ticaret-hukuku-10', 226, 'Bağımsız denetim eşiğinde borsada işlem görmeyen halka açık sayılan şirket üçlüsü **30 milyon aktif - 40 milyon net satış - 50 çalışan**dır.', 0),
  ('ticaret-hukuku-227', 'ticaret-hukuku-10', 227, 'Denetimde (II) liste üçlüsü **120 milyon aktif - 150 milyon net satış - 100 çalışan**dır.', 1),
  ('ticaret-hukuku-228', 'ticaret-hukuku-10', 228, 'Denetimde diğer şirket üçlüsü **300 milyon aktif - 600 milyon net satış - 150 çalışan**dır.', 2),
  ('ticaret-hukuku-229', 'ticaret-hukuku-10', 229, 'Denetim eşik yolunda **3 ölçütten en az 2’si art arda 2 hesap döneminde aşılır**; (I) liste **eşiksizdir**.', 3),
  ('ticaret-hukuku-230', 'ticaret-hukuku-10', 230, 'SPK’nın belirtilen kuruluş/ihraççıları; BDDK finans kuruluşları; sigorta/reasürans/emeklilik ve ilgili BİST kıymetli maden grubu **eşiksiz listededir**.', 4),
  ('ticaret-hukuku-231', 'ticaret-hukuku-10', 231, 'Lisanslı depolar, umumi mağazalar, ilgili EPDK şirketleri, TCMB ödeme/e-para kuruluşları ve 233 sayılı KHK kapsamı **eşiksiz listededir**.', 5),
  ('ticaret-hukuku-232', 'ticaret-hukuku-10', 232, 'RTÜK grubunda ulusal karasal, uydu ve çok ile kablolu TV haklarından **en az 2’si** veya ayrıca **internette isteğe bağlı yayın hakkı** eşiksiz listeye girer.', 6),
  ('ticaret-hukuku-233', 'ticaret-hukuku-10', 233, 'TMS’de borsada işlem görmeyen halka açık sayılanların özel üçlüsü **15 milyon aktif - 20 milyon net satış - 50 çalışan**dır.', 7),
  ('ticaret-hukuku-234', 'ticaret-hukuku-10', 234, 'TMS’de Hazine ve Maliye izinli A grubu müessese üçlüsü **7,5 milyon aktif - 250 milyon brüt satış - 25 çalışan**dır; iki özel grupta **en az 2 ölçüt** sağlanır.', 8),
  ('ticaret-hukuku-235', 'ticaret-hukuku-10', 235, 'Denetçi **3568’e göre ruhsatlı YMM/SMMM ve KGK yetkilisi** olmalı; bu ortaklardan oluşan sermaye şirketi de denetçi olabilir.', 9),
  ('ticaret-hukuku-236', 'ticaret-hukuku-10', 236, 'Denetlenecek şirkette **pay sahibi olmak**, yönetici/çalışan olmak veya **önceki 3 yılda** bu sıfatı taşımak denetçilik engelidir.', 10),
  ('ticaret-hukuku-237', 'ticaret-hukuku-10', 237, 'Bağlantılı şirkette **%20’den fazla** pay ve belirtilen çalışma ilişkileri; YK/yöneticinin **3. derece dâhil kan/kayın hısımlığı** denetçilik engelidir.', 11),
  ('ticaret-hukuku-238', 'ticaret-hukuku-10', 238, 'Şirket defterini/tablelerini hazırlamada denetim dışı katkı veren kişi, kendi işini **denetleyemez**.', 12),
  ('ticaret-hukuku-239', 'ticaret-hukuku-10', 239, 'Son **5 yılda** mesleki gelirinin **%30’dan fazlasını** şirketten/ona %20’den fazla iştiraklilerden elde edip cari yılda da beklemek engeldir.', 13),
  ('ticaret-hukuku-240', 'ticaret-hukuku-10', 240, 'Rotasyon **10 yılda toplam 7 yıl** aynı şirket denetiminden sonra **3 yıl ara**dır; vergi danışmanlığı/denetimi dışı hizmet verilemez.', 14),
  ('ticaret-hukuku-241', 'ticaret-hukuku-10', 241, 'Denetçiyi **her dönem GK**, topluluk denetçisini **ana şirket GK’sı** seçer; YK tescil, TTSG ve site ilanını yapar.', 15),
  ('ticaret-hukuku-242', 'ticaret-hukuku-10', 242, 'Taraflı denetçiyi değiştirmek için **YK veya %10/%5 azlık** mahkemeye gider; **4. aya kadar seçilememe** hâlinde tek ortak/tek YK üyesi de başvurabilir.', 16),
  ('ticaret-hukuku-243', 'ticaret-hukuku-10', 243, 'TMSF kayyımlığındaki şirkette 4. aya kadar seçim yoksa **YK teklifiyle ilişkili Bakan** atar; yetki Fon Kuruluna devredilebilir.', 17),
  ('ticaret-hukuku-244', 'ticaret-hukuku-10', 244, 'Denetçi fesih ihbarında **YK hemen geçici denetçi seçip GK onayına** sunar.', 18),
  ('ticaret-hukuku-245', 'ticaret-hukuku-10', 245, 'Denetçi raporu **imzalayıp YK’ya** verir; tablolar **TMS’ye**, denetim **Türkiye Denetim Standartlarına** göre değerlendirilir.', 19),
  ('ticaret-hukuku-246', 'ticaret-hukuku-10', 246, 'Görüş türleri **olumlu, sınırlı olumlu, olumsuz ve kaçınma**dır; **sınırlı olumsuz** yoktur.', 20),
  ('ticaret-hukuku-247', 'ticaret-hukuku-10', 247, 'Olumsuz görüşte YK, **teslimden 4 iş gününde GK’yı çağırır**; GK yeni YK seçer, yeni YK **6 ayda** uygun tabloları raporla sunar.', 21),
  ('ticaret-hukuku-248', 'ticaret-hukuku-10', 248, 'Görüş vermekten kaçınma **olumsuz görüşün sonuçlarını** doğurur; ES aksini demiyorsa eski YK üyeleri yeniden seçilebilir.', 22),
  ('ticaret-hukuku-249', 'ticaret-hukuku-10', 249, 'Denetçinin genel sorumluluğu **m.554’te kusura**, sır saklama sorumluluğu özel olarak **m.404’e** tabidir.', 23),
  ('ticaret-hukuku-250', 'ticaret-hukuku-10', 250, 'Denetçi gerekirse tablolar çıkarılmadan ve ana/yavru şirkette bilgi ister; YK tabloları/yıllık raporu **onaylayıp gecikmeksizin verir**.', 24)
insert into public.sections (id, lesson_id, title, emoji, sort) values ('ticaret-hukuku-11', 'ticaret-hukuku', 'Sermaye değişikliği ve borçlanma araçları', '💰', 11) on conflict (id) do update set title = excluded.title, emoji = excluded.emoji, sort = excluded.sort;
insert into public.cards (id, section_id, number, text, sort) values
  ('ticaret-hukuku-251', 'ticaret-hukuku-11', 251, 'ES değişikliğini **GK** kararlaştırır; müktesep/vazgeçilmez haklar saklıdır ve gerekli Bakanlık izni yoksa **değişiklik GK’da görüşülemez**.', 0),
  ('ticaret-hukuku-252', 'ticaret-hukuku-11', 252, 'ES değişikliği üçüncü kişiye **tescilden önce** hüküm ifade etmez.', 1),
  ('ticaret-hukuku-253', 'ticaret-hukuku-11', 253, 'Esas sermayede artırım organı **GK**, kayıtlı sermayede **ES tavanı içinde YK**dır.', 2),
  ('ticaret-hukuku-254', 'ticaret-hukuku-11', 254, 'Başlangıç sermayesi **asgari çıkarılmış**, çıkarılmış sermaye **satılmış payları**, kayıtlı sermaye **YK’nın çıkarabileceği tavanı** ifade eder.', 3),
  ('ticaret-hukuku-255', 'ticaret-hukuku-11', 255, 'Kayıtlıda imtiyazlı/primli pay ve rüçhan sınırlaması için **ES’de özel YK yetkisi**; açıkta ayrıca itibari altı pay ve imtiyaz kısıtlama yetkisi mümkündür.', 4),
  ('ticaret-hukuku-256', 'ticaret-hukuku-11', 256, 'İmtiyaz haklarını ihlal eden yetkilendirme/artırım kararı **imtiyazlı özel kurul onayı olmadan uygulanamaz**.', 5),
  ('ticaret-hukuku-257', 'ticaret-hukuku-11', 257, 'Sermayeye eklenebilir bilanço fonları dönüştürülmeden yalnız dış kaynak taahhüdüyle artırılamaz; **SerPK m.12/6 özel uygulanmama kuralı** saklıdır.', 6),
  ('ticaret-hukuku-258', 'ticaret-hukuku-11', 258, 'İç kaynağı aşan eşzamanlı dış artırımda PDF’nin aktardığı Genelge, **iç kaynağın tamamının eklenmesini ve tüm payların hazır olduğu GK’da oybirliğini** arar.', 7),
  ('ticaret-hukuku-259', 'ticaret-hukuku-11', 259, 'Şarta bağlı artırım **ayrı sermaye sistemi değil özel yöntemdir**; değiştirme/alım hakkı **kullanıldığında ve kullanıldığı ölçüde** sermaye artar.', 8),
  ('ticaret-hukuku-260', 'ticaret-hukuku-11', 260, 'Şarta bağlı artırım, belirtilen borçlanma aracı alacaklıları veya **çalışanlara pay alma hakkı** için kullanılabilir; ES dayanağı ve tescil gerekir.', 9),
  ('ticaret-hukuku-261', 'ticaret-hukuku-11', 261, 'Azaltım organı kayıtlıda da **GK**; ihtiyaç fazlasını azaltma **kurucu**, bilanço açığını kapatma **açıklayıcı** niteliktedir.', 10),
  ('ticaret-hukuku-262', 'ticaret-hukuku-11', 262, 'Azaltım sonrası **alacaklıları tam karşılayan aktif** kalmalı ve sermaye **kanuni asgarinin altına** inmemelidir.', 11),
  ('ticaret-hukuku-263', 'ticaret-hukuku-11', 263, 'TTK azaltım nisabı **tüm sermayenin en az %75 olumlu oyu**; halka açık özel SerPK nisabı saklıdır.', 12),
  ('ticaret-hukuku-264', 'ticaret-hukuku-11', 264, 'Azaltım ilanı **7 gün arayla 3 kez**; alacaklı ödeme/teminat istemi **3. ilandan 2 ayda** yapılır.', 13),
  ('ticaret-hukuku-265', 'ticaret-hukuku-11', 265, 'Azaltımda bilanço açığını **açık oranında** kapatmada YK çağrı ve ödeme/teminat sürecinden vazgeçebilir.', 14),
  ('ticaret-hukuku-266', 'ticaret-hukuku-11', 266, 'Alacaklının azaltım iptali davası **tescilin ilanından 2 yıl içinde** merkezdeki asliye ticarette açılır.', 15),
  ('ticaret-hukuku-267', 'ticaret-hukuku-11', 267, 'İntifa senedini **GK** çıkarır; net kâr/tasfiye bakiyesi/yeni pay menfaati verebilir fakat **ortaklık sıfatı ve GK oyu vermez**.', 16),
  ('ticaret-hukuku-268', 'ticaret-hukuku-11', 268, 'İntifa senedi **emre veya hamiline**; tahvil **emre, nama veya hamiline** çıkarılabilir.', 17),
  ('ticaret-hukuku-269', 'ticaret-hukuku-11', 269, 'Para, çek, poliçe ve kambiyo bonosu menkul kıymet tanımının dışındadır; **depo sertifikası menkul kıymettir**, varant borçlanma aracı değildir.', 18),
  ('ticaret-hukuku-270', 'ticaret-hukuku-11', 270, 'Borçlanma ihracında kural organ **GK**; kapalıda kural **%75 tüm sermaye**, açıkta özel rejimle **adi nisap** uygulanır.', 19),
  ('ticaret-hukuku-271', 'ticaret-hukuku-11', 271, 'TTK m.505’te YK’ya ihraç yetkisi devri **en çok 15 ay**; SerPK m.31/3’te **ES ile süreli/süresiz** yapılabilir.', 20),
  ('ticaret-hukuku-272', 'ticaret-hukuku-11', 272, 'Borçlanma aracı bedeli **nakit** olup **teslim anında tamamen** ödenir.', 21),
  ('ticaret-hukuku-273', 'ticaret-hukuku-11', 273, 'Özel Tebliğde genel borçlanma ihraç limiti açıkta **özkaynağın 5 katı**, kapalıda **3 katıdır**; konsolidasyonda **ana ortaklık özkaynağı** esas alınır.', 22)
insert into public.sections (id, lesson_id, title, emoji, sort) values ('ticaret-hukuku-12', 'ticaret-hukuku', 'Payın bastırılması, devri ve geri alımı', '📜', 12) on conflict (id) do update set title = excluded.title, emoji = excluded.emoji, sort = excluded.sort;
insert into public.cards (id, section_id, number, text, sort) values
  ('ticaret-hukuku-274', 'ticaret-hukuku-12', 274, 'Primli pay için **ES hükmü veya GK kararı**; kayıtlıda özel YK yetkisi gerekir ve **değişken sermayeli yatırım ortaklığı payının itibari değeri yoktur**.', 0),
  ('ticaret-hukuku-275', 'ticaret-hukuku-12', 275, 'Pay şirkete karşı bölünemez; ortak maliklerde **ortak temsilci**, yoksa birine tebligat **tümüne geçerlidir**.', 1),
  ('ticaret-hukuku-276', 'ticaret-hukuku-12', 276, 'Sermaye aynı kalırken payları birleştirmek için **her pay sahibinin onayı** gerekir.', 2),
  ('ticaret-hukuku-277', 'ticaret-hukuku-12', 277, 'Tam ödenmemiş pay için **hamiline senet çıkarılamaz**; tescilden önce çıkarılan senet geçersizken taahhüt borcu sürer.', 3),
  ('ticaret-hukuku-278', 'ticaret-hukuku-12', 278, 'Hamiline senedi YK **tam ödemeden itibaren 3 ayda** bastırıp dağıtır; bastırma kararı tescil/ilan ve siteye konulur.', 4),
  ('ticaret-hukuku-279', 'ticaret-hukuku-12', 279, 'Hamiline pay/hak sahibi bilgileri **senet dağıtılmadan MKK’ya** bildirilir; PDF’de bu ihlalin cezası **20.000 TL idari paradır**.', 5),
  ('ticaret-hukuku-280', 'ticaret-hukuku-12', 280, 'Azlık isterse **nama senet bastırılıp tüm nama pay sahiplerine** dağıtılır; ilmühabere **nama senet hükümleri** kıyasen uygulanır.', 6),
  ('ticaret-hukuku-281', 'ticaret-hukuku-12', 281, 'Nama senedin hamiline dönüşümünde **bedelin tamamı ödenmiş** olmalıdır; kural ES değişikliğidir.', 7),
  ('ticaret-hukuku-282', 'ticaret-hukuku-12', 282, 'Hamiline devir **zilyetlik aktarımı ve devralanın MKK bildirimi** gerektirir; bildirim yoksa haklar kullanılamaz ve PDF’de ceza **5.000 TL’dir**.', 8),
  ('ticaret-hukuku-283', 'ticaret-hukuku-12', 283, 'Nama senet **ciro ve teslimle**, senetsiz nama pay **alacağın devriyle**, kaydî pay **elektronik kayıt aktarımıyla** devredilir.', 9),
  ('ticaret-hukuku-284', 'ticaret-hukuku-12', 284, 'Nama payda şirketle ilişkide **pay defterindeki kişi** tanınır; hamiline paya ES ile devir kısıtı getirilemez.', 10),
  ('ticaret-hukuku-285', 'ticaret-hukuku-12', 285, 'Tam ödenmemiş nama payda onay reddi için **ödeme yeterliliği şüphesi ve istenen teminatın verilmemesi** gerekir; miras/mal rejimi/cebrî icra istisnadır.', 11),
  ('ticaret-hukuku-286', 'ticaret-hukuku-12', 286, 'Tasfiyeye girildiğinde **ES’ye dayalı nama pay devir sınırlamaları düşer**.', 12),
  ('ticaret-hukuku-287', 'ticaret-hukuku-12', 287, 'Kote olmayan nama payda ret **ES’de önemli sebep, gerçek değerden satın alma önerisi veya kendi adına/hesabına alma beyanı eksikliğine** dayanır.', 13),
  ('ticaret-hukuku-288', 'ticaret-hukuku-12', 288, 'Kote olmayanda miras vb. özel edinimde ret **yalnız gerçek değerden alım önerisiyle** mümkündür; kote payda bu edinim **reddedilemez**.', 14),
  ('ticaret-hukuku-289', 'ticaret-hukuku-12', 289, 'Kote payda ret yalnız **ES’de yüzdeyle belirlenen iktisap üst sınırının aşılması veya istenen kendi adına/hesabına alma beyanının yokluğuyla** mümkündür.', 15),
  ('ticaret-hukuku-290', 'ticaret-hukuku-12', 290, 'Kote olmayan normal devirde onaya kadar **mülkiyet ve tüm haklar devredende** kalır; miras vb. hâlde mali haklar hemen, katılım/oy onayla geçer.', 16),
  ('ticaret-hukuku-291', 'ticaret-hukuku-12', 291, 'Şirket onay istemini **3 ayda reddetmezse veya ret haksızsa** onay verilmiş sayılır.', 17),
  ('ticaret-hukuku-292', 'ticaret-hukuku-12', 292, 'Mahkemede belirlenen gerçek değeri öğrendikten **1 ayda reddetmeyen** devralan öneriyi kabul etmiş sayılır; değerleme giderini şirket öder.', 18),
  ('ticaret-hukuku-293', 'ticaret-hukuku-12', 293, 'Kendi payını ivazlı edinme/rehin kabulünün genel sınırı **esas/çıkarılmış sermayenin %10’u**; GK’nın YK yetkisi **en çok 5 yıldır**.', 19),
  ('ticaret-hukuku-294', 'ticaret-hukuku-12', 294, 'İvazsız edinim yasak değildir; belirli özel edinimler kural olarak **3 yılda** elden çıkarılır, şirket+yavru toplamı %10’u aşmıyorsa istisna vardır.', 20),
  ('ticaret-hukuku-295', 'ticaret-hukuku-12', 295, 'Aykırı edinilen/rehin alınan kendi payı **edinim/rehinden en geç 6 ayda** çıkarılır/rehni kaldırılır; işlem otomatik geçersiz değildir.', 21),
  ('ticaret-hukuku-296', 'ticaret-hukuku-12', 296, 'Şirket kendi payını **taahhüt edemez** ve kendi tek ortağı olamaz; aykırı taahhütte kuruluşta kurucu, artırımda YK bedelden sorumludur, kusursuzluk ispatı saklıdır.', 22)
insert into public.sections (id, lesson_id, title, emoji, sort) values ('ticaret-hukuku-13', 'ticaret-hukuku', 'Ortaklık hakları, kâr ve rüçhan', '🤝', 13) on conflict (id) do update set title = excluded.title, emoji = excluded.emoji, sort = excluded.sort;
insert into public.cards (id, section_id, number, text, sort) values
  ('ticaret-hukuku-297', 'ticaret-hukuku-13', 297, 'Tablolar, yıllık/denetim raporu ve kâr önerisi **GK’dan en az 15 gün önce** incelemeye hazır olur; finansal/konsolide tablolar **1 yıl** açık tutulur.', 0),
  ('ticaret-hukuku-298', 'ticaret-hukuku-13', 298, 'Ortak bilanço/gelir tablosu suretini **şirket gideriyle** ister; defter/yazışmanın ilgili kısmı **GK izni veya YK kararıyla** incelenir.', 1),
  ('ticaret-hukuku-299', 'ticaret-hukuku-13', 299, 'Ortak bilgi istemi reddinde **reddi izleyen 10 günde**; cevapsızlık/ertelemede **makul süre sonra** merkezdeki asliye ticarete gider; karar kesindir.', 2),
  ('ticaret-hukuku-300', 'ticaret-hukuku-13', 300, 'Bilgi önceden bir ortağa verilmişse diğerine talebi üzerine **aynı kapsamda, gündem dışı olsa da** verilir; bu durumda sır gerekçeli ret hükmüne dayanılmaz.', 3),
  ('ticaret-hukuku-301', 'ticaret-hukuku-13', 301, 'Özel denetim isteminde **bilgi/inceleme hakkı önceden kullanılmış olmalı**; her ortak gündem dışı da olsa GK’ya başvurabilir.', 4),
  ('ticaret-hukuku-302', 'ticaret-hukuku-13', 302, 'GK kabulünde **şirket veya her ortak 30 günde**; ret hâlinde **%10/%5 azlık veya en az 1 milyon TL itibari pay sahibi 3 ayda** mahkemeye gider.', 5),
  ('ticaret-hukuku-303', 'ticaret-hukuku-13', 303, 'Özel denetçiyi **mahkeme atar**, rapor önce **mahkemeye**, sonra YK aracılığıyla ilk GK’ya gider; ortak **GK’dan sonraki 1 yılda** suret ister.', 6),
  ('ticaret-hukuku-304', 'ticaret-hukuku-13', 304, 'Özel denetimde gider kural olarak **şirketindir**; özel şartlarda başvurana yüklenebilir, GK kabul etmişse şirket öder.', 7),
  ('ticaret-hukuku-305', 'ticaret-hukuku-13', 305, 'Kâr payı yalnız **net dönem kârı ve serbest yedeklerden**, **GK kararıyla** dağıtılır.', 8),
  ('ticaret-hukuku-306', 'ticaret-hukuku-13', 306, 'Birinci kanuni yedek **yıllık kârın %5’i** olup **ödenmiş sermayenin %20’sine** ulaşıncaya kadar ayrılır; ES artırabilir.', 9),
  ('ticaret-hukuku-307', 'ticaret-hukuku-13', 307, 'PDF’nin dağıtım sırasında ilk kâr payı **ödenmiş sermayenin %5’i**; ikinci yedek ilk pay sonrasında dağıtılacak toplamın **%10’udur**.', 10),
  ('ticaret-hukuku-308', 'ticaret-hukuku-13', 308, 'Haksız ve kötü niyetli alınan kâr payı/hazırlık faizi iadesi **paranın alındığı tarihten 5 yılda** zamanaşımına uğrar.', 11),
  ('ticaret-hukuku-309', 'ticaret-hukuku-13', 309, 'Açıkta kâr payı dağıtım tarihindeki tüm paylara edinim tarihi gözetilmeden verilir; **kıstelyevm uygulanmaz**.', 12),
  ('ticaret-hukuku-310', 'ticaret-hukuku-13', 310, 'Açıkta avans toplamı **önceki yıl dönem kârının yarısını** aşamaz; eski avans mahsup edilmeden yeni avans/kâr dağıtımı kararı verilemez.', 13),
  ('ticaret-hukuku-311', 'ticaret-hukuku-13', 311, 'SerPK kâr payı/avansı Tebliği **II-19.1**; kapalı avansında düzenleyen kurum **Ticaret Bakanlığıdır**.', 14),
  ('ticaret-hukuku-312', 'ticaret-hukuku-13', 312, 'Sermayeye faiz kural olarak yasaktır; hazırlık faizi **ES’ye dayalı, TMS’ye uygun ve özellikli varlık maliyetine** yüklenir.', 15),
  ('ticaret-hukuku-313', 'ticaret-hukuku-13', 313, 'Yeni yatırımla genişlemede hazırlık faizi **en geç yatırımın işletmeye alındığı güne kadar** ödenebilir.', 16),
  ('ticaret-hukuku-314', 'ticaret-hukuku-13', 314, 'Rüçhan **mevcut pay oranında yeni pay önceliğidir**, devredilebilir ve YK kullanım için **en az 15 gün** verir.', 17),
  ('ticaret-hukuku-315', 'ticaret-hukuku-13', 315, 'TTK’da rüçhan kısıtlaması **tüm esas sermayenin %60 olumlu oyu ve haklı sebep** gerektirir; açıkta özel SerPK nisabı uygulanır.', 18),
  ('ticaret-hukuku-316', 'ticaret-hukuku-13', 316, 'Rüçhan doğrudan ES ile kaldırılamaz; kayıtlıda **ES’nin özel yetki verdiği YK** karar verebilir ve nisap dışındaki şartlar sürer.', 19),
  ('ticaret-hukuku-317', 'ticaret-hukuku-13', 317, 'Önerilmeye muhatap olma hakkının konusu **dönüştürme/alım hakkı içeren borçlanma aracıdır**; çalışanlara doğrudan alım hakkında uygulanmaz.', 20),
  ('ticaret-hukuku-318', 'ticaret-hukuku-13', 318, 'Önerilmeye muhatap olmanın kısıtlanmasında **%60 uygulanması PDF’de bir görüştür**; kanunda açık nisap değildir.', 21),
  ('ticaret-hukuku-319', 'ticaret-hukuku-13', 319, 'Azlık oranları **kapalı %10/açık %5**; bireysel bilgi alma, katılma ve genel koruyucu haklar için bu oran aranmaz.', 22),
  ('ticaret-hukuku-320', 'ticaret-hukuku-13', 320, 'Pay devri onaya bağlıysa ES, ortağa **tekrarlanan ve para olmayan ikincil edim** yükleyebilir; ikincil yük kararı **tüm sermayenin oybirliğini** gerektirir.', 23)
insert into public.sections (id, lesson_id, title, emoji, sort) values ('ticaret-hukuku-14', 'ticaret-hukuku', 'Sona erme ve tasfiye', '🏁', 14) on conflict (id) do update set title = excluded.title, emoji = excluded.emoji, sort = excluded.sort;
insert into public.cards (id, section_id, number, text, sort) values
  ('ticaret-hukuku-321', 'ticaret-hukuku-14', 321, 'Süre dolması, konu gerçekleşmesi/imkânsızlığı, ES sebebi, GK kararı, şirket iflası ve diğer kanuni sebepler AŞ’yi sona erdirir; **YK başkanının iflası şirketi bitirmez**.', 0),
  ('ticaret-hukuku-322', 'ticaret-hukuku-14', 322, 'Süresi dolsa da işe fiilen devam eden şirket **belirsiz süreli hâle** gelebilir.', 1),
  ('ticaret-hukuku-323', 'ticaret-hukuku-14', 323, 'Organ eksikliğinde **pay sahibi, alacaklı veya Ticaret Bakanlığı** başvurur; mahkeme YK’yı dinleyip önce **düzeltme süresi** verir.', 2),
  ('ticaret-hukuku-324', 'ticaret-hukuku-14', 324, 'Haklı sebeple feshi **%10/%5 azlık** ister; mahkeme fesih yerine **karara en yakın gerçek pay değerini ödetip çıkarma veya başka çözüm** seçebilir.', 3),
  ('ticaret-hukuku-325', 'ticaret-hukuku-14', 325, 'Ticaret Bakanlığı m.210/3 aykırılık/muvazaasında **öğrenmeden 1 yıl içinde** fesih davası açabilir.', 4),
  ('ticaret-hukuku-326', 'ticaret-hukuku-14', 326, 'Tasfiye boyunca **tüzel kişilik sürer**, unvana **tasfiye hâlinde** eklenir ve organ yetkileri tasfiye amacıyla sınırlıdır.', 5),
  ('ticaret-hukuku-327', 'ticaret-hukuku-14', 327, 'Tasfiye memurunu **ES/GK**, mahkeme feshinde **mahkeme** atar; atama yoksa **YK** tasfiyeyi yapar.', 6),
  ('ticaret-hukuku-328', 'ticaret-hukuku-14', 328, 'Temsile yetkili tasfiye memurlarından **en az biri hem Türk vatandaşı hem Türkiye’de yerleşik** olmalıdır.', 7),
  ('ticaret-hukuku-329', 'ticaret-hukuku-14', 329, 'GK, ES/GK ile atanan memuru alabilir; **mahkemenin atadığını alamaz** ve tek ortağın haklı sebep başvurusuyla mahkeme değiştirebilir.', 8),
  ('ticaret-hukuku-330', 'ticaret-hukuku-14', 330, 'Tasfiyede önemli aktiflerin toptan satışı **GK’nın tüm sermayede en az %75 olumlu oyunu** gerektirir; sonraki toplantıda aynı nisap sürer.', 9),
  ('ticaret-hukuku-331', 'ticaret-hukuku-14', 331, 'Tasfiye memurları başlangıç **envanter ve bilançosunu GK onayına** sunar; tasfiyenin gerektirmediği yeni iş yapamaz.', 10),
  ('ticaret-hukuku-332', 'ticaret-hukuku-14', 332, 'Bilinen alacaklıya **taahhütlü mektup**, diğerlerine **1 hafta arayla 3 ilan** yapılır.', 11),
  ('ticaret-hukuku-333', 'ticaret-hukuku-14', 333, 'Bilinen alacaklı bildirmezse karşılık **Bakanlığın belirlediği bankaya**; vadesi gelmemiş/çekişmeli borç karşılığı kural olarak **notere** depo edilir.', 12),
  ('ticaret-hukuku-334', 'ticaret-hukuku-14', 334, 'Yeterli teminat veya dağıtımın borcun ödenmesine bağlanması varsa **notere depo gerekmez**.', 13),
  ('ticaret-hukuku-335', 'ticaret-hukuku-14', 335, 'Borçlar aktiften fazlaysa memurlar derhâl **merkezdeki asliye ticarete** bildirir; iflas açılır.', 14),
  ('ticaret-hukuku-336', 'ticaret-hukuku-14', 336, 'Dağıtım sırası **borçlar, pay bedelleri, bakiye**; ES aksini demiyorsa bakiye ödenmiş sermaye/imtiyaz oranında, ES/GK aksini demiyorsa **para olarak** dağıtılır.', 15),
  ('ticaret-hukuku-337', 'ticaret-hukuku-14', 337, 'Tasfiye bakiyesi **3. alacaklı çağrısından 3 ay geçmeden** dağıtılamaz; tehlike yoksa **mahkeme erken dağıtıma izin verebilir**.', 16),
  ('ticaret-hukuku-338', 'ticaret-hukuku-14', 338, 'Terkini **tasfiye memurları** ister; tüzel kişilik **sicilden terkinle** son bulur.', 17),
  ('ticaret-hukuku-339', 'ticaret-hukuku-14', 339, 'Ek tasfiyeyi **son tasfiye memurları, son YK üyeleri, ortaklar veya alacaklılar** ister; **denetçi ve sicil memuru isteyemez**.', 18),
  ('ticaret-hukuku-340', 'ticaret-hukuku-14', 340, 'Ek tasfiyeye **merkezdeki asliye ticaret mahkemesi** karar verir, memurları yeniden atar ve tescil **bildiricidir**.', 19),
  ('ticaret-hukuku-341', 'ticaret-hukuku-14', 341, 'Ek tasfiye **eksik işi tamamlar**; yeni alacaklı çağrısı/bekleme dönemi gerekmez ve şirket tasfiye amacıyla sınırlı kalır.', 20),
  ('ticaret-hukuku-342', 'ticaret-hukuku-14', 342, 'Tasfiyeden dönme, **süre dolması veya GK kararıyla sona ermede** ve ortaklara malvarlığı dağıtımına başlanmamışsa mümkündür.', 21),
  ('ticaret-hukuku-343', 'ticaret-hukuku-14', 343, 'Tasfiyeden dönmeye **GK, tüm sermayenin en az %60 olumlu oyuyla** karar verir; ES ağırlaştırabilir.', 22),
  ('ticaret-hukuku-344', 'ticaret-hukuku-14', 344, 'Çok küçük pay bedeli/tasfiye payı iadesi bile dönmeyi engeller; **parayı geri vermek engeli kaldırmaz**.', 23),
  ('ticaret-hukuku-345', 'ticaret-hukuku-14', 345, 'Dönme kararını **tasfiye memuru tescil/ilan ettirir**; tescil **kurucudur** ve şirket ticari faaliyete devam eder.', 24),
  ('ticaret-hukuku-346', 'ticaret-hukuku-14', 346, 'İflasın kaldırılması veya konkordato uygulamasıyla bitmesi, dağıtım başlamama şartıyla PDF’de **zımni tasfiyeden dönme** sayılır.', 25)
